<?php
function render_editor_form(array $article,string $actionLabel,string $csrf,array $site): void {
$covers=['assets/images/blog-default.svg'=>'Studio violet','assets/images/cover-code.svg'=>'Code nocturne','assets/images/cover-creative.svg'=>'Créatif lumineux'];?>
<div class="editor-layout"><section class="editor-main-card"><div class="editor-title-row"><div><span class="eyebrow-text">ÉDITEUR</span><h1><?=e($actionLabel)?></h1></div><a href="<?=e(app_url('admin.php'))?>">← Dashboard</a></div><label class="editor-title-input"><span>Titre</span><input name="title" value="<?=e($article['title']??'')?>" required maxlength="220" placeholder="Une idée qui mérite d’être partagée"></label><label><span>Résumé</span><textarea name="excerpt" rows="3" maxlength="500" placeholder="Une phrase pour donner envie de lire…"><?=e($article['excerpt']??'')?></textarea></label><label><span>Contenu</span><textarea class="content-editor" name="content" rows="18" required placeholder="Écrivez votre histoire, votre tutoriel, votre retour d’expérience…"><?=e($article['content']??'')?></textarea></label><div class="field-grid"><label><span>Catégorie</span><input name="category" value="<?=e($article['category']??'Développement')?>" maxlength="80"></label><label><span>Tags</span><input name="tags" value="<?=e($article['tags']??'')?>" maxlength="240" placeholder="php, web, open-source"></label></div><div class="seo-box"><div><strong>SEO</strong><span>Facultatif, mais utile pour le partage.</span></div><label><span>Titre SEO</span><input name="seo_title" value="<?=e($article['seo_title']??'')?>" maxlength="220"></label><label><span>Description SEO</span><textarea name="seo_description" rows="2" maxlength="320"><?=e($article['seo_description']??'')?></textarea></label></div></section><aside class="editor-side-card"><div class="publish-box"><h3>Publication</h3><label><span>Statut</span><select name="status"><option value="draft" <?=($article['status']??'draft')==='draft'?'selected':''?>>Brouillon</option><option value="published" <?=($article['status']??'')==='published'?'selected':''?>>Publié</option></select></label><label class="toggle-row"><input type="checkbox" name="featured" value="1" <?=!empty($article['featured'])?'checked':''?>><span>Mettre à la une</span></label><button class="btn btn-primary btn-full"><?=e($actionLabel)?> <span>→</span></button></div><div class="image-box"><h3>Image de l’article</h3><p>Choisissez une image intégrée ou collez une URL HTTPS. En hébergement classique, vous pouvez aussi téléverser un fichier.</p><div class="cover-choice-grid"><?php foreach($covers as $path=>$label):?><label class="cover-choice"><input type="radio" name="builtin_image" value="<?=e($path)?>" <?=($article['image']??'')===$path?'checked':''?>><img src="<?=e(app_url($path))?>" alt=""><span><?=e($label)?></span></label><?php endforeach;?></div><label><span>URL externe</span><input name="image_url" value="<?=e((str_starts_with((string)($article['image']??''),'http'))?$article['image']:'')?>" placeholder="https://..."></label><label><span>Ou fichier local</span><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"></label></div><div class="site-context"><img src="<?=e(safe_asset_url($site['avatar'],'assets/images/avatar-default.svg'))?>" alt=""><div><span>Publication pour</span><strong><?=e($site['name'])?></strong></div></div></aside></div><?php }
